import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 18 Electric currents in modern art","description":"学习 感官动词后的补语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 18 Electric currents in modern art","description":"学习 感官动词后的补语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 感官动词后的补语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 17 The longest suspension bridge in the world","link":"/life/english/new-concept/book-3/unit-01/lesson-017"},"next":{"text":"第三册：培养技能 · Lesson 19 A very dear cat","link":"/life/english/new-concept/book-3/unit-01/lesson-019"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 17 The longest suspension bridge in the world","link":"/life/english/new-concept/book-3/unit-01/lesson-017"},"next":{"text":"第三册：培养技能 · Lesson 19 A very dear cat","link":"/life/english/new-concept/book-3/unit-01/lesson-019"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-018.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-018.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-018.md"};function r(l,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-18-electric-currents-in-modern-art" tabindex="-1">第三册：培养技能 · Lesson 18 Electric currents in modern art <a class="header-anchor" href="#第三册-培养技能-·-lesson-18-electric-currents-in-modern-art" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 18 Electric currents in modern art&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕需要观众参与的艺术装置，练习说明一个动作正在发生还是被完整观察到。评价作品时先描述装置如何运行，再表达个人感受。学习感官动词后两种补语的区别，避免在看到、听到之后随意加 to，并能把直接观察与解释分开。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>installation</td><td>/ˌɪnstəˈleɪʃən/</td><td>n.</td><td>装置作品</td><td>an interactive installation</td></tr><tr><td>current</td><td>/ˈkʌrənt/</td><td>n.</td><td>电流</td><td>an electric current</td></tr><tr><td>rotate</td><td>/rəʊˈteɪt/</td><td>v.</td><td>旋转</td><td>rotate slowly</td></tr><tr><td>response</td><td>/rɪˈspɒns/</td><td>n.</td><td>反应</td><td>a visible response</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>set in motion — 使开始运转</li><li>in response to — 作为对某刺激的反应</li></ul><h2 id="语法讲解-感官动词后的补语" tabindex="-1">语法讲解：感官动词后的补语 <a class="header-anchor" href="#语法讲解-感官动词后的补语" aria-label="Permalink to &quot;语法讲解：感官动词后的补语&quot;">​</a></h2><p>see、hear、watch、notice 等动词后可用宾语加动词原形，强调观察到完整动作或动作事实；也可用宾语加 ing，强调动作正在进行的片段。主动结构一般不用 to，如 saw the light flash。变为被动时，原形结构通常恢复 to，例如 was seen to leave；ing 结构仍保留 ing。实际语境可能让两种形式都成立，但表达视角不同。描述作品时，先报告感官证据，再给出解读，不能把自己的解释写成眼睛直接看到的事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We watched the metal rings rotating while a low tone filled the room.</p></blockquote><p>低沉的声音充满房间时，我们看着金属环不断旋转。</p><p>watched 加宾语 the metal rings 和 rotating，呈现观看中的持续动作；while 连接同时背景。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>We saw the panel to move 在主动感官结构中多了 to；应写 move 或 moving，取决于观察视角。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比读 saw it move 和 saw it moving；给同伴或录音留出明显的 ing 尾音，判断听者能否分辨动作视角。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I noticed a red disk moving behind the glass. It slowed down when visitors stopped clapping. The changing rhythm made the room feel unexpectedly quiet.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描述一件虚构互动作品，先写观察，再写机制和感受。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>前两句描述可观察变化，第三句才表达体验。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改正：I heard the bell to ring.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I heard the bell ring.</p><p><strong>解析：</strong> 主动 hear 加宾语后用动词原形表达动作事实。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句强调完整转完一次还是正在旋转？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 正在旋转。</p><p><strong>解析：</strong> rotating 呈现过程。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 People saw him leave 改成被动。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He was seen to leave.</p><p><strong>解析：</strong> 被动感官结构恢复 to。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：感官动词后的补语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-017">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-019">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
